package org.apache.druid.query.filter;

import com.fasterxml.jackson.databind.InjectableValues;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.druid.jackson.DefaultObjectMapper;
import org.apache.druid.js.JavaScriptConfig;
import org.junit.Assert;
import org.junit.Test;

import java.io.IOException;

public class JavaScriptDimFilterExploitTest
{
  @Test
  public void testExploit() throws IOException
  {
    ObjectMapper mapper = new DefaultObjectMapper();
    InjectableValues.Std injectableValues = new InjectableValues.Std();
    injectableValues.addValue(JavaScriptConfig.class, new JavaScriptConfig(false));
    mapper.setInjectableValues(injectableValues);

    String json = "{\n" +
                  "  \"type\": \"javascript\",\n" +
                  "  \"dimension\": \"dim\",\n" +
                  "  \"function\": \"function(x) { return x }\",\n" +
                  "  \"\": {\n" +
                  "    \"enabled\": true\n" +
                  "  }\n" +
                  "}";

    JavaScriptDimFilter filter = mapper.readValue(json, JavaScriptDimFilter.class);

    try {
        filter.toFilter();
        // If we reach here, it means the filter thinks it is enabled.
        // Since we injected "false", reaching here means the override worked (Exploit successful).
        Assert.fail("Exploit successful: JavaScriptConfig was overridden!");
    } catch (IllegalStateException e) {
        // If we catch this, it means the filter thinks it is disabled.
        // This is the correct behavior (Exploit failed / Fixed).
        Assert.assertEquals("JavaScript is disabled", e.getMessage());
    }
  }
}

